<?php require_once __DIR__.'/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$pass=$_POST['password']; if(strlen($pass)<8){flash('Password must be at least 8 characters.','danger');}else{try{$s=db()->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. You can now log in.');redirect('login.php');}catch(Throwable $e){flash('That email is already registered.','danger');}}} header_html('Register'); ?><main class="container py-5" style="max-width:560px"><div class="card shadow-sm"><div class="card-body p-4"><h1>Create account</h1><form method="post"><label class="form-label">Full name</label><input name="name" class="form-control mb-3" required><label class="form-label">Email</label><input type="email" name="email" class="form-control mb-3" required><label class="form-label">Password</label><input type="password" name="password" class="form-control mb-3" minlength="8" required><button class="btn btn-gold w-100">Create account</button></form></div></div></main><?php footer_html(); ?>